53	// TestCreateDraftRejectsInvalidUTF8 覆盖新建草稿：任何夹带无效 UTF-8 的正文
54	// 都返回 ErrInvalidArgument，不留下新记录、不产生任何状态变化（关闭重开
55	// 后同样不存在）。诊断与医嘱两个类别都适用。空白正文继续按既有规则拒绝。
56	func TestCreateDraftRejectsInvalidUTF8(t *testing.T) {
57		for _, category := range []string{Diagnosis, Order} {
58			for _, tc := range invalidContents {
59				t.Run(category+"/"+tc.label, func(t *testing.T) {
60					dir := t.TempDir()
61					clk := &fakeClock{t: time.Date(2026, 5, 1, 9, 0, 0, 0, time.UTC)}
62					open := func() *Store {
63						s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
64						if err != nil {
65							t.Fatalf("open: %v", err)
66						}
67						return s
68					}
69	
70					s := open()
71					p, err := s.RegisterPatient(doc, "无效UTF8新建草稿患者")
72					if err != nil {
73						t.Fatal(err)
74					}
75					e, err := s.AddEncounter(doc, p.ID, time.Time{})
76					if err != nil {
77						t.Fatal(err)
78					}
79	
80					before := countRecords(s)
81					if _, err := s.CreateDraft(doc, p.ID, e.ID, category, tc.content); !errors.Is(err, ErrInvalidArgument) {
82						t.Fatalf("CreateDraft(%q) err = %v, want ErrInvalidArgument", tc.content, err)
83					}
84					// 拒绝新建不能留下新记录：档案与记录数都与提交前一致。
85					if got := countRecords(s); got != before {
86						t.Fatalf("rejected create left records: count before=%d after=%d", before, got)
87					}
88					chart, err := s.Chart(doc, p.ID)
89					if err != nil {
90						t.Fatal(err)
91					}
92					if len(chart.Records) != 0 {
93						t.Fatalf("rejected create left a record: %+v", chart.Records)
94					}
95					// 坏字节没有被落盘：关闭重开后仍无记录。
96					s = reopenStore(t, s, dir, clk)
97					if got := countRecords(s); got != before {
98						t.Fatalf("rejected create persisted after reopen: count=%d", got)
99					}
100					chart, err = s.Chart(doc, p.ID)
101					if err != nil {
102						t.Fatal(err)
103					}
104					if len(chart.Records) != 0 {
105						t.Fatalf("rejected create left a record after reopen: %+v", chart.Records)
106					}
107					_ = s.Close()
108				})
109			}
110		}
111	
112		// 空串与全空白正文继续按既有规则拒绝。
113		s, _ := newTestStore(t)
114		pid, eid := setupPatientEncounter(t, s)
115		for _, blank := range []string{"", " ", "\n\t\r ", "　"} {
116			if _, err := s.CreateDraft(doc, pid, eid, Diagnosis, blank); !errors.Is(err, ErrInvalidArgument) {
117				t.Fatalf("CreateDraft blank content %q err = %v, want ErrInvalidArgument", blank, err)
118			}
119		}
120		if got := countRecords(s); got != 0 {
121			t.Fatalf("blank creates left records: %d", got)
122		}
123	
124		// 接收方身份不能新建草稿：既有身份权限保持不变。
125		if _, err := s.CreateDraft(rcv, pid, eid, Diagnosis, "接收方试图建草稿"); !errors.Is(err, ErrAccessDenied) {
126			t.Fatalf("receiver CreateDraft err = %v, want ErrAccessDenied", err)
127		}
128	}
