168				}
169	
170				// 关闭后从同一位置重新打开：正文逐字保持。
171				s = reopenStore(t, s, dir, clk)
172				t.Cleanup(func() { _ = s.Close() })
173				chart, err = s.Chart(doc, p.ID)
174				if err != nil {
175					t.Fatal(err)
176				}
