179					t.Fatalf("draft content after reopen = %+v, want %q", hist, tc.content)
180				}
181	
182				// 生效后第 1 版固化同一份原文，重开后仍一致。
183				v1, err := s.ActivateRecord(doc, r.ID)
184				if err != nil {
185					t.Fatal(err)
186				}
187				if v1.Content != tc.content {
188					t.Fatalf("activated content = %q, want %q", v1.Content, tc.content)
189				}
190				s = reopenStore(t, s, dir, clk)
191				t.Cleanup(func() { _ = s.Close() })
192				chart, err = s.Chart(doc, p.ID)
193				if err != nil {
194					t.Fatal(err)
195				}
196				hist = findHistory(chart, r.ID)
197				if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.Content != tc.content {
198					t.Fatalf("active content after reopen = %+v, want %q", hist, tc.content)
199				}
200			})
201		}
202	}
